<?php
session_start();
if (empty($_SESSION['usuario_id']) || ($_SESSION['usuario_rol'] ?? '') !== 'admin') { http_response_code(403); exit('Acceso restringido.'); }
require_once __DIR__.'/../backend/conexion.php';
if (empty($_SESSION['csrf_admin'])) $_SESSION['csrf_admin']=bin2hex(random_bytes(32));
$csrf=$_SESSION['csrf_admin']; $mod=$_GET['mod']??'categorias';
$mods=['categorias'=>'Categorías','cupones'=>'Cupones','envios'=>'Tarifas de envío','config'=>'Configuración','notificaciones'=>'Notificaciones','chatbot'=>'Preguntas del chatbot','analitica'=>'Analítica','auditoria'=>'Auditoría'];
if (!isset($mods[$mod])) $mod='categorias'; $msg='';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function audit($pdo,$accion,$entidad=null,$id=null,$detalle=null){$q=$pdo->prepare('INSERT INTO auditoria_admin(admin_id,accion,entidad,entidad_id,detalle) VALUES(?,?,?,?,?)');$q->execute([$_SESSION['usuario_id'],$accion,$entidad,$id,$detalle]);}
if ($_SERVER['REQUEST_METHOD']==='POST') {
 if (!hash_equals($csrf,$_POST['csrf']??'')) { http_response_code(419); exit('Token de seguridad inválido. Recarga la página.'); }
 try {
  $action=$_POST['action']??'';
  if ($mod==='categorias' && $action==='save') { $id=(int)($_POST['id']??0);$n=trim($_POST['nombre']??'');$d=trim($_POST['descripcion']??''); if(!$n)throw new RuntimeException('Escribe el nombre.'); if($id){$q=$pdo->prepare('UPDATE categorias SET nombre=?,descripcion=? WHERE id=?');$q->execute([$n,$d,$id]);}else{$q=$pdo->prepare('INSERT INTO categorias(nombre,descripcion) VALUES(?,?)');$q->execute([$n,$d]);} audit($pdo,'guardar_categoria','categorias',$id?:$pdo->lastInsertId(),$n);$msg='Categoría guardada.'; }
  elseif($mod==='categorias' && $action==='toggle'){ $q=$pdo->prepare('UPDATE categorias SET activa=1-activa WHERE id=?');$q->execute([(int)$_POST['id']]);audit($pdo,'cambiar_estado_categoria','categorias',$_POST['id']);$msg='Estado actualizado.'; }
  elseif($mod==='cupones' && $action==='save'){ $id=(int)($_POST['id']??0);$code=strtoupper(trim($_POST['codigo']??''));$type=$_POST['tipo']??'porcentaje';$value=(float)($_POST['valor']??0);$min=(float)($_POST['minimo']??0);$max=($_POST['maximo']??'')!==''?(int)$_POST['maximo']:null;$start=$_POST['inicia']?:null;$end=$_POST['vence']?:null;if(!$code||$value<=0||!in_array($type,['porcentaje','monto'],true)||($type==='porcentaje'&&$value>100))throw new RuntimeException('Revisa código y valor del cupón.');if($id){$q=$pdo->prepare('UPDATE cupones SET codigo=?,tipo=?,valor=?,minimo_compra=?,usos_maximos=?,inicia_en=?,vence_en=? WHERE id=?');$q->execute([$code,$type,$value,$min,$max,$start,$end,$id]);}else{$q=$pdo->prepare('INSERT INTO cupones(codigo,tipo,valor,minimo_compra,usos_maximos,inicia_en,vence_en) VALUES(?,?,?,?,?,?,?)');$q->execute([$code,$type,$value,$min,$max,$start,$end]);}audit($pdo,'guardar_cupon','cupones',$id?:$pdo->lastInsertId(),$code);$msg='Cupón guardado.';}
  elseif($mod==='cupones' && $action==='toggle'){$q=$pdo->prepare('UPDATE cupones SET activo=1-activo WHERE id=?');$q->execute([(int)$_POST['id']]);audit($pdo,'cambiar_estado_cupon','cupones',$_POST['id']);$msg='Estado actualizado.';}
  elseif($mod==='envios' && $action==='save'){$prov=trim($_POST['provincia']??'');$dist=trim($_POST['distrito']??'');$cost=(float)($_POST['costo']??-1);$days=trim($_POST['dias']??'1 a 3 días');if(!$prov||!$dist||$cost<0)throw new RuntimeException('Completa provincia, distrito y costo válido.');$q=$pdo->prepare('INSERT INTO tarifas_envio(provincia,distrito,costo,dias_estimados) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE costo=VALUES(costo),dias_estimados=VALUES(dias_estimados),activa=1');$q->execute([$prov,$dist,$cost,$days]);audit($pdo,'guardar_tarifa_envio','tarifas_envio',null,$prov.' / '.$dist);$msg='Tarifa guardada.';}
  elseif($mod==='envios' && $action==='toggle'){$q=$pdo->prepare('UPDATE tarifas_envio SET activa=1-activa WHERE id=?');$q->execute([(int)$_POST['id']]);audit($pdo,'cambiar_tarifa_envio','tarifas_envio',$_POST['id']);$msg='Estado actualizado.';}
  elseif($mod==='config' && $action==='save'){foreach(($_POST['valores']??[]) as $key=>$value){$q=$pdo->prepare('INSERT INTO configuracion(clave,valor) VALUES(?,?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)');$q->execute([$key,trim((string)$value)]);}audit($pdo,'actualizar_configuracion','configuracion',null,'Parámetros generales');$msg='Configuración guardada.';}
  elseif($mod==='notificaciones' && $action==='send'){$uid=($_POST['usuario_id']??'')!==''?(int)$_POST['usuario_id']:null;$title=trim($_POST['titulo']??'');$body=trim($_POST['mensaje']??'');$type=trim($_POST['tipo']??'general');if(!$title||!$body)throw new RuntimeException('Completa título y mensaje.');$q=$pdo->prepare('INSERT INTO notificaciones(usuario_id,titulo,mensaje,tipo) VALUES(?,?,?,?)');$q->execute([$uid,$title,$body,$type]);audit($pdo,'crear_notificacion','notificaciones',$pdo->lastInsertId(),$title);$msg='Notificación registrada dentro de la tienda.';}
  elseif($mod==='chatbot' && $action==='save'){$id=(int)($_POST['id']??0);$question=trim($_POST['pregunta']??'');$keys=trim($_POST['palabras']??'');$answer=trim($_POST['respuesta']??'');if(!$question||!$answer)throw new RuntimeException('Completa pregunta y respuesta.');if($id){$q=$pdo->prepare('UPDATE chatbot_faq SET pregunta=?,palabras_clave=?,respuesta=? WHERE id=?');$q->execute([$question,$keys,$answer,$id]);}else{$q=$pdo->prepare('INSERT INTO chatbot_faq(pregunta,palabras_clave,respuesta) VALUES(?,?,?)');$q->execute([$question,$keys,$answer]);}audit($pdo,'guardar_faq','chatbot_faq',$id?:$pdo->lastInsertId(),$question);$msg='Respuesta del chatbot guardada.';}
  elseif($mod==='chatbot' && $action==='toggle'){$q=$pdo->prepare('UPDATE chatbot_faq SET activa=1-activa WHERE id=?');$q->execute([(int)$_POST['id']]);audit($pdo,'cambiar_estado_faq','chatbot_faq',$_POST['id']);$msg='Estado actualizado.';}
 } catch(Throwable $e){$msg='No se pudo guardar: '.$e->getMessage();}
}
$rows=[];
if($mod==='categorias')$rows=$pdo->query('SELECT * FROM categorias ORDER BY nombre')->fetchAll();
if($mod==='cupones')$rows=$pdo->query('SELECT * FROM cupones ORDER BY id DESC')->fetchAll();
if($mod==='envios')$rows=$pdo->query('SELECT * FROM tarifas_envio ORDER BY provincia,distrito')->fetchAll();
if($mod==='config')$rows=$pdo->query('SELECT * FROM configuracion ORDER BY clave')->fetchAll();
if($mod==='chatbot')$rows=$pdo->query('SELECT * FROM chatbot_faq ORDER BY orden,id')->fetchAll();
if($mod==='notificaciones')$rows=$pdo->query('SELECT n.*,u.email FROM notificaciones n LEFT JOIN usuarios u ON u.id=n.usuario_id ORDER BY n.id DESC LIMIT 100')->fetchAll();
if($mod==='analitica'){$rows=$pdo->query('SELECT evento,COUNT(*) total,DATE(creado_en) fecha FROM eventos_analitica WHERE creado_en>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY evento,DATE(creado_en) ORDER BY fecha DESC,total DESC LIMIT 150')->fetchAll();}
if($mod==='auditoria')$rows=$pdo->query('SELECT a.*,u.email FROM auditoria_admin a LEFT JOIN usuarios u ON u.id=a.admin_id ORDER BY a.id DESC LIMIT 200')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($mods[$mod])?> | Xiaomi Store</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#202124;font:15px Arial,sans-serif}.bar{background:#171717;color:white;padding:17px max(4%,calc((100% - 1200px)/2));display:flex;gap:18px;align-items:center;flex-wrap:wrap}.bar a{color:white;text-decoration:none}.wrap{max-width:1200px;margin:28px auto;padding:0 18px}.nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.nav a,.btn{padding:9px 12px;border-radius:8px;background:#fff;color:#222;text-decoration:none;border:1px solid #ddd}.nav a.active,.primary{background:#e53935;color:#fff;border-color:#e53935}.panel{background:white;padding:20px;border-radius:14px;margin-bottom:18px;box-shadow:0 5px 24px #00000008}.formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:6px}.field input,.field select,.field textarea{padding:11px;border:1px solid #d8dce1;border-radius:8px;font:inherit}.field textarea{min-height:85px}.btn{cursor:pointer}.msg{padding:12px;background:#fff4e5;border-radius:8px;margin-bottom:15px}table{width:100%;border-collapse:collapse;min-width:650px}td,th{text-align:left;padding:11px;border-bottom:1px solid #edf0f2;vertical-align:top}th{color:#69717c}.tablewrap{overflow:auto}.muted{color:#69717c;font-size:13px}.actions{display:flex;gap:7px;flex-wrap:wrap}form.inline{display:inline}@media(max-width:600px){.bar{align-items:flex-start;flex-direction:column}.panel{padding:14px}}</style></head><body><header class="bar"><b>Xiaomi Store Arequipa · Administración</b><a href="index.php">Dashboard</a><a href="../index.php">Ver tienda</a><a href="../backend/logout.php">Cerrar sesión</a></header><main class="wrap"><h1><?=h($mods[$mod])?></h1><nav class="nav"><?php foreach($mods as $key=>$label):?><a class="<?=($key===$mod?'active':'')?>" href="?mod=<?=h($key)?>"><?=h($label)?></a><?php endforeach?></nav><?php if($msg):?><div class="msg"><?=h($msg)?></div><?php endif?>
