<?php elseif($mod==='cupones'):?><section class="panel"><h2>Crear cupón</h2><form method="post" class="formgrid"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="save"><label class="field">Código<input name="codigo" required placeholder="XIAOMI10"></label><label class="field">Tipo<select name="tipo"><option value="porcentaje">Porcentaje</option><option value="monto">Monto fijo (S/)</option></select></label><label class="field">Valor<input name="valor" type="number" min="0.01" step="0.01" required></label><label class="field">Compra mínima<input name="minimo" type="number" min="0" step="0.01" value="0"></label><label class="field">Usos máximos<input name="maximo" type="number" min="1" placeholder="Sin límite"></label><label class="field">Inicia<input name="inicia" type="datetime-local"></label><label class="field">Vence<input name="vence" type="datetime-local"></label><div><button class="btn primary">Guardar cupón</button></div></form></section><section class="panel tablewrap"><table><tr><th>Código</th><th>Descuento</th><th>Usos</th><th>Vigencia</th><th>Estado</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['codigo'])?></td><td><?=h($r['tipo']==='porcentaje'?$r['valor'].'%':'S/ '.$r['valor'])?></td><td><?=$r['usos_actuales']?> / <?=h($r['usos_maximos']??'∞')?></td><td><?=h($r['inicia_en']??'Inmediato')?> – <?=h($r['vence_en']??'Sin vencimiento')?></td><td><?=$r['activo']?'Activo':'Inactivo'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn">Cambiar estado</button></form></td></tr><?php endforeach?></table></section>
